"""One-time resolution of the Rust branch against the pinned TypeScript merge."""
import json
import re
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TARGET = "53b9b86956c963fbed74cb5cf84c66fff6503fa5"


def git(*args, check=True):
    return subprocess.run(["git", *args], cwd=ROOT, text=True, capture_output=True, check=check)


def change(path, before, after):
    file = ROOT / path
    text = file.read_text()
    if before not in text:
        raise RuntimeError(f"Expected source changed in {path}: {before[:100]!r}")
    file.write_text(text.replace(before, after))


head = git("rev-parse", "HEAD").stdout.strip()
base = git("merge-base", head, TARGET).stdout.strip()
if base == TARGET:
    raise RuntimeError("The target is already merged; do not repeat this migration.")
ours = set(git("diff", "--name-only", base, head).stdout.splitlines())
theirs = set(git("diff", "--name-only", base, TARGET).stdout.splitlines())
merge = git("merge", "--no-commit", "--no-ff", TARGET, check=False)
print(merge.stdout, merge.stderr)
if merge.returncode not in (0, 1):
    raise RuntimeError("Git merge failed before conflict resolution")
# Adopt the merged language interfaces and port Rust below. Unique files on
# either side and unrelated changes remain in the ordinary three-way merge.
shared = sorted(ours & theirs)
if shared:
    git("restore", "--source=" + TARGET, "--staged", "--worktree", "--", *shared)
if git("diff", "--name-only", "--diff-filter=U").stdout.strip():
    raise RuntimeError("Unexpected unresolved path outside the shared integration surface")
print("Reconciled shared paths:", "\n".join(shared))

# One classifier for all languages; retain TS extension, test, header and config
