path = "adapters/opencode/lib/github.ts"
change(path, 'isTestSource, isReadableContext, isGeneratedSource', 'isTestSource, isReadableSource, isGeneratedSource, isBuildOutput, rustScopeNote, type SourceLanguage')
change(path, 'type ChangedFile = { path: string;', 'type ChangedFile = { path: string; language?: SourceLanguage;')
change(path, '  if (isTestSource(path)) return "test file";', '  if (isTestSource(path)) return "test file";\n  if (isBuildOutput(path)) return "Rust build-output path";')
change(path, '      exclusion: exclusion(f.filename, f.status),', '      exclusion: exclusion(f.filename, f.status),\n      language: sourceLanguage(f.filename),')
change(path, '    const allowed = Boolean(sourceLanguage(path)) || isReadableContext(path);\n    if (!allowed || isTestSource(path) || isInternalPath(path)) {', '    if (!isReadableSource(path)) {')
